import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { useRef } from "react";
import { shake } from "@/registry/erbium/lib/shake";
import { Button } from "@/registry/erbium/ui/button";

export default function ShakeExample() {
  const ref = useRef<HTMLButtonElement>(null);

  return (
    <Button
      ref={ref}
      variant="error"
      onClick={() => {
        shake(ref.current);
      }}
    >
      Replay error feedback
    </Button>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";



const meta = {
  parameters: {
    docs: { description: { component: "## Usage\n\nReplays error feedback on an element without changing its validation state. The animation respects the reduced motion preference and RTL direction.\n\nImport `shake` from `@/registry/erbium/lib/shake` and call it with an element ref. Calling it again on the same element restarts the animation instead of stacking a second one.\n\nInside a TanStack Form you do not call `shake` yourself: `field.Field` and every bound field shake on a rejected submit. See [Form](/docs/components/form). Call it directly for feedback outside a form, such as a failed action on a single control." } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Utilities/Shake",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { useRef } from \"react\";\nimport { shake } from \"@/registry/erbium/lib/shake\";\nimport { Button } from \"@/registry/erbium/ui/button\";\n\nexport default function ShakeExample() {\n  const ref = useRef<HTMLButtonElement>(null);\n\n  return (\n    <Button\n      ref={ref}\n      variant=\"error\"\n      onClick={() => {\n        shake(ref.current);\n      }}\n    >\n      Replay error feedback\n    </Button>\n  );\n}\n" },
    },
  },
  render: OverviewExample,
};

import ShakeExample from "../examples/shake-demo";

const Example = () => <ShakeExample />;

export default Example;
